function validate([nums, target]) {
  if (nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each value is a whole number from 1 to 100.';
  if (!Number.isInteger(target) || target < 1 || target > 100) return 'target is a whole number from 1 to 100.';
  return null;
}

