function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const top = size === 'large' ? 100 : 6;
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  // Usually pick a value that occurs; sometimes any value, which may be missing.
  const target = rand() < 0.7 ? nums[Math.floor(rand() * n)] : 1 + Math.floor(rand() * top);
  return [nums, target];
}
